/** icon("school") → inline 24px SVG. Unknown names render an empty box rather than throw. */
export function icon(name, { size = 24, cls = "", label = "" } = {}) {
  const body = P[name] || "";
  const a11y = label ? `role="img" aria-label="${label.replace(/"/g, "&quot;")}"` : `aria-hidden="true"`;
  return `<svg class="ic${cls ? " " + cls : ""}" viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor" ${a11y}>${body}</svg>`;
}

export const hasIcon = (name) => Object.prototype.hasOwnProperty.call(P, name);
